// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
sampler sampler_pw_noise_lq;
#define GP GetPixel
const vec2 hor = vec2 (.005,0.00) * 6.0;
const vec2 ver = vec2 (-0.00,.005) * 6.0;
float k,ym, blur, ret1, wi, f0;
vec2 dz;

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  ret = 0;
f0 = 2;
dz.x = f0*(GP(uv+hor) - GP(uv-hor)).r;
dz.y = f0*(GP(uv+ver) - GP(uv-ver)).r;
blur = GetBlur1(uv).r;
k=blur.r * -6.0+1;
ym=uv.y-.5;
dz = multiply(dz,mat2(cos(k),sin(k),-sin(k),cos(k)));
if (sign(dz.y*ym)<0) {dz.y*=1.0 - abs(ym) * 4.0;}
wi = 0.12;
ret1 = -blur*wi + (1.0 + wi)*GP(uv+dz*.004).r;
ret.r = max(0.8*GetBlur2(uv).r,ret1)*0.99;
ret.r -= clamp01(texture(sampler_noise_lq,uv.x*0.05+uTime).r-q25) *abs(ym)*.2;
  fragColor = vec4(ret, 1.0);
}

