{float x;
if (abs(re) > abs(im))
{x = matan (im/re);
if (re<0) {x += M_PI;}
}
else
{x = M_PI / 2.0 -matan (re/im);
if (im<0) {x += M_PI;}
}
//  return (x>=M_PI? x - 2.0*M_PI: x);
return x;}
