vec2 otria (vec2 x) {return  4.0 * pow (fract(x)-0.5, 2.0 );}
vec2 costria (vec2 x) {return sat(8.0 * abs (fract(x)-0.5)-1.5);} //entspr. dem cosinus (x*6.28)
vec2 tria (vec2 x) {return 2.0 * abs(fract(x)-.5);}
float elight (vec2 uvi) {return sat(.02/sqrt(length (otria(uvi/(2.0 * M_PI))))-0.017);}
vec3 RotXYZ (vec3 p, vec3 speed)
{ vec3 c = cos (speed);
vec3 s = sin (speed);
vec3 q=p;
q= vec3 (q.x, q.y*c.x - q.z*s.x, q.y*s.x + q.z*c.x);
q= vec3 (q.x*c.y + q.z*s.y, q.y, -q.x*s.y + q.z*c.y);
q= vec3 (q.x*c.z - q.y*s.z, q.x*s.z + q.y*c.z, q.z);
return q;}
float GetDist(vec3 p)
{ float res, res1;
p = p + vec3(torus1rad, 0.0 , 0.0 );
float x = length(p.xz)-torus1rad;
float umf = matan2 (p.x,p.z)*torus1rad+scenepos ;
float wind;
res = .5*length(vec2(x, p.y));
float y_ = p.y*compy;
float x_ = abs(x);
if (y_<0) //Obere Haelfte !
{
wind = sat(1.05-x_);
res1 =  abs(y_)-wind*compy ;
}
else //Untere Haelfte
{
res1 = min(bridge + 2.0*x_ - 0.5*sat(4.0 * y_ - 5.0), abs(y_));
