li *= !isLava;
ret = tex + li*(wall+isWindow)*float3 (0.5,0.6,1);
//Lava
float2 uvl = frac(uv20-.5);
float ll = max(p.y>1,.3*!bridge*sat(pow(1*p.y-.38,2)));
float3 lav1 = lerp (((GetBlur3(uvl)*0.75+GetPixel(uvl)).r),GetBlur3(float2(uvl.x,0.5)).r*wall, !isLava);
ret += ll*lav1*lavcol;
//PAINT
float sel = sat(4*tria(uv20.x*0.125)-2);
uv4 = 0.5 + (1.0 - abs( frac(uv20 * 0.25) * 2 - 1.0 )-.5); //already defined above !
uv4 = (uv4-.5)*texzoom+.5;
wtex[0]= 0;
wtex[1] = tex2D(rand01,uv4);
wtex[2] = tex2D(rand02,uv4);
wtex[3] = tex2D(rand03,uv4);
paint = lerp (wtex[seltex1],wtex[seltex2]*tex1lum,sel);
ret += ((0.15+wall))*paint *sat(1-0.6*abs(norm.y))*sat(3-2*abs(p.y))*.75;
ret += abs(p.z) *fog * (1-isLava*.5) * slow_roam_cos; //NEBEL
ret.r += 2*sat(.0005/length(otria(uv20.xy-.5)) * (abs(uv20.y)<0.2)) * (tex1lum);
//ret -= sat(rad/2-.35);
