#define sat clamp01
sampler sampler_pw_noise_lq;
sampler rand01, rand02, rand03, martin_skin_emergency_power_supply;
const float quality = 100;
const float scenepos = q20, torus1rad=q15, torus1dia=1, zoom=q10, texstr_x=q9,
compy=1.25, f_intens=q30, s_intens=q26, texzoom=q4, tex1lum=q14,torusdir = q11,
seltex1=q12, seltex2=q13, selmod=q6, fog=q7, bridge=q8;
const vec3 scenerot = vec3 (q21,q22,q23), lanpos = vec3 (q16,q17,q18),
camerapos = vec3(q1, q2, q3), flpos = vec3(q31,-5,q32),
shapepos=vec3 (q27,q28,q29), lavcol = vec3 (1.5,0.6, 0.0 ) ;
float isWindow, isLava, seltex, side, lmod;
vec2 uv0, uv4, uv20, uv30, rs;
vec3 tex,tmp3, rd, p, pm, pl, norm, bel, diff, wall, paint;
mat4 wtex;
float matan (float x)
{return x*(1.061 - abs(x)*0.274);}
float matan2 (float im, float re) //Version ohne Pruefing auf ( 0.0 , 0.0 );
{float x;
if (abs(re) > abs(im))
{x = matan (im/re);
if (re<0) {x += M_PI;}
}
else
{x = M_PI / 2.0 -matan (re/im);
if (im<0) {x += M_PI;}
}
//  return (x>=M_PI? x - 2.0*M_PI: x);
return x;}
vec3 noise3 (vec2 uvi)
{return texture(sampler_noise_mq,uvi)+0.5*texture(sampler_noise_mq,uvi * 3.0)-.75;}
vec2 otria (vec2 x) {return  4.0 * pow (fract(x)-0.5, 2.0 );}
vec2 costria (vec2 x) {return sat(8.0 * abs (fract(x)-0.5)-1.5);} //entspr. dem cosinus (x*6.28)
vec2 tria (vec2 x) {return 2.0 * abs(fract(x)-.5);}
float elight (vec2 uvi) {return sat(.02/sqrt(length (otria(uvi/(2.0 * M_PI))))-0.017);}
vec3 RotXYZ (vec3 p, vec3 speed)
{ vec3 c = cos (speed);
vec3 s = sin (speed);
vec3 q=p;
q= vec3 (q.x, q.y*c.x - q.z*s.x, q.y*s.x + q.z*c.x);
q= vec3 (q.x*c.y + q.z*s.y, q.y, -q.x*s.y + q.z*c.y);
q= vec3 (q.x*c.z - q.y*s.z, q.x*s.z + q.y*c.z, q.z);
return q;}
float GetDist(vec3 p)
{ float res, res1;
p = p + vec3(torus1rad, 0.0 , 0.0 );
float x = length(p.xz)-torus1rad;
float umf = matan2 (p.x,p.z)*torus1rad+scenepos ;
float wind;
res = .5*length(vec2(x, p.y));
float y_ = p.y*compy;
float x_ = abs(x);
if (y_<0) //Obere Haelfte !
{
wind = sat(1.05-x_);
res1 =  abs(y_)-wind*compy ;
}
else //Untere Haelfte
{
res1 = min(bridge + 2.0*x_ - 0.5*sat(4.0 * y_ - 5.0), abs(y_));
if (y_>compy) {res-=1;}
}
return torus1dia-max(res,res1) ;
}
float GetDist2(vec3 p)
{ float res, res1;
p = p + vec3(torus1rad, 0.0 , 0.0 );
float x = length(p.xz)-torus1rad;
res = .5*length(vec2(x, p.y));
//  res = 0.5*max(abs(x),abs(p.y)); //ist das billiger ????
float y_ = p.y*compy;
float x_ = abs(x);
return torus1dia-0.5*max(x_,res) ;
}
float RayMarch(vec3 ro, vec3 rd) //Tunnel wall
{
float dO=0.1;
float dS = 1;
while (dS > 1.0 / quality)
{
dS = GetDist(ro + rd * dO);
dO += dS;
}
return dO;}
float RayMarch2(vec3 ro, vec3 rd) //Refl. layer
{
float dO=0.1;
float dS = 1;
while (dS > 4.0 / quality)
{
dS = GetDist2(ro + rd * dO);
dO += dS;
}
return dO;}
vec3 GetNormal(vec3 p)
{
vec2 e = vec2(0.05, 0.0 );
vec3 n = GetDist(p).x-vec3(GetDist(p-e.xyy).x, GetDist(p-e.yxy).x, GetDist(p-e.yyx).x);
return normalize(n);
}
vec3 makewall (vec2 uvi)
{return texture(martin_skin_emergency_power_supply,uvi);}
shader_body
{
vec2 uv0 = uv_orig;
uv= (uv_orig-0.5)*uAspect.xy;
rd = vec3 (uv/zoom*vec2( 1.0 ,torusdir), 1.0 );
rd=RotXYZ(rd,scenerot);
p  = camerapos + rd*RayMarch(camerapos,rd);
pm = camerapos + rd*RayMarch2(camerapos,rd);
norm = GetNormal(p);
isLava = p.y>2;
tmp3= p+vec3(torus1rad, 0.0 , 0.0 );
side = sign(length(tmp3.xz)-torus1rad);
float xlim =matan2 (tmp3.x, tmp3.z)*torus1rad;
uv20.x = (xlim +scenepos)*texstr_x;
uv20.y = (matan2(length(tmp3.xz)-torus1rad, -tmp3.y)) * 2.0/M_PI;
tmp3= pm+ vec3(torus1rad, 0.0 , 0.0 );
uv30.x = (matan2 (tmp3.x, tmp3.z)*torus1rad +scenepos)*texstr_x;
uv30.y = (tmp3.y / 2.0*compy/torus1dia);
uv4 = 0.5 + (1.0 - abs( fract(uv20 * 0.25) * 2.0 - 1.0 )-.5);
wall = makewall(uv4);
isWindow = sat (2-50*wall.g)*(p.y<-1.2);
diff.x = lum(wall-makewall(uv4+(vec2(1.0)/uTexSize)*vec2( 1.0 , 0.0 )))*(isWindow == 0.0 ? 1.0 : 0.0);
diff.y = lum(wall-makewall(uv4+(vec2(1.0)/uTexSize)*vec2( 0.0 , 1.0 )))*(isWindow == 0.0 ? 1.0 : 0.0);
//tunnel lights
rs = vec2(uv20.x * 3.0,uv20.y)*M_PI;//* 3 = Synchron zur wall; besser waere (wg. abwechhslungsreicherer Spiegelung) KEINE Sync ?
bel = elight(rs);
wall = mix(wall, 0.2, sat(bel * 4.0-2));
lmod = mix((texture(sampler_pw_noise_lq,rs.x / 512.0/M_PI+side / 256.0).r>= .8-audioMidSmooth / 4.0),
sat(-1+2*costria((uv20.x+q5+side*1.5) / 2.0/M_PI)), selmod);
bel *= lmod;
//mirrored lights
rs = vec2(uv30.x * 3.0,uv30.y)*M_PI ;
lmod = mix((texture(sampler_pw_noise_lq,rs.x / 512.0/M_PI+side / 256.0).r>= 0.8-audioMidSmooth / 4.0),
sat(-1+2*costria((uv20.x+q5+side*1.5) / 2.0/M_PI)), selmod);
vec3 mirbel = sat(elight(rs+diff * 2.0) * 2.0)*(norm.x==0)*(p.y>0);
mirbel*=(wall+(fract(wall * 3.0)))*lmod * exp(-abs(pm.z)*.03125);
//TEX
tex = wall * sat (1-.0*abs(norm.y));
tex = mix(tex*(4.0 * bel+isLava*.1+.05*lavcol+0.02), 1.0 ,bel>0.5) + mirbel ;
//LIGHTNING
float lz = abs(1.0 / rd.y);
vec2 uv7 = vec2 (rd.x, 1.0 )*lz*vec2(0.02,0.005)-flpos;
vec2 cld= (noise3(uv7.xy+wall.r*.05));
vec3 l = normalize(flpos-p);
float li0=0.07*sat(dot(norm,l));
float li = f_intens*mix(li0,(.2/length(lz-flpos.z-cld * 4.0))*(1-2*wall.b), isWindow);
li *= (isLava == 0.0 ? 1.0 : 0.0);
ret = tex + li*(wall+isWindow)*vec3 (0.5,0.6, 1.0 );
//Lava
vec2 uvl = fract(uv20-.5);
float ll = max(p.y>1,.3*(bridge == 0.0 ? 1.0 : 0.0)*sat(pow(1.0 * p.y-.38, 2.0 )));
vec3 lav1 = mix(((GetBlur3(uvl)*0.75+GetPixel(uvl).xy).r),GetBlur3(vec2(uvl.x,0.5)).r*wall, (isLava == 0.0 ? 1.0 : 0.0));
ret += ll*lav1*lavcol;
//PAINT
float sel = sat(4.0 * tria(uv20.x*0.125) - 2.0);
uv4 = 0.5 + (1.0 - abs( fract(uv20 * 0.25) * 2.0 - 1.0 )-.5); //already defined above !
uv4 = (uv4-.5)*texzoom+.5;
wtex[0]= 0;
wtex[1] = texture(rand01,uv4);
wtex[2] = texture(rand02,uv4);
wtex[3] = texture(rand03,uv4);
paint = mix(wtex[seltex1],wtex[seltex2]*tex1lum,sel);
ret += ((0.15+wall))*paint *sat(1-0.6*abs(norm.y))*sat(3-2*abs(p.y))*.75;
ret += abs(p.z) *fog * (1.0 - isLava*.5) * slow_roam_cos; //NEBEL
ret.r += 2.0 * sat(.0005/length(otria(uv20.xy-.5)) * (abs(uv20.y)<0.2)) * (tex1lum);
//ret -= sat(rad / 2.0-.35);
//ret = GetPixel(uv0).r;
}
